param([string]$VictimVmName='XDR-Victim-Sprint18',[string]$CredentialPath='D:\VMs\XDR-Victim-Sprint18\victim-credential.xml')
$ErrorActionPreference='Stop';$root=Resolve-Path(Join-Path $PSScriptRoot '..\..');Set-Location $root
& (Join-Path $PSScriptRoot 'sprint31-final-reconciliation.ps1') -VictimVmName $VictimVmName -CredentialPath $CredentialPath
$base=Get-Content artifacts/sprint31-final-reconciliation.json -Raw|ConvertFrom-Json
$cfg=@{};Get-Content .env|Where-Object{$_-match'^\s*([^#=\s]+)=(.*)$'}|ForEach-Object{$cfg[$matches[1]]=$matches[2].Trim().Trim('"').Trim("'")};$token=(Invoke-RestMethod -Method Post 'http://127.0.0.1:8080/api/v1/auth/token' -ContentType application/json -Body(@{username=$cfg.PLATFORM_BOOTSTRAP_USER;password=$cfg.PLATFORM_BOOTSTRAP_PASSWORD}|ConvertTo-Json -Compress)).access_token;$h=@{Authorization="Bearer $token"}
$detections=(Invoke-RestMethod 'http://127.0.0.1:8080/api/v1/detection-rules' -Headers $h).data;$correlations=(Invoke-RestMethod 'http://127.0.0.1:8080/api/v1/correlation-rules' -Headers $h).data;$catalog=(Invoke-RestMethod 'http://127.0.0.1:8080/api/v1/detection-content/catalog' -Headers $h).data
$report=[ordered]@{schemaVersion='sprint32-final-reconciliation.v1';capturedAt=[DateTimeOffset]::UtcNow.ToString('o');postgres=$base.postgres;openSearch=$base.openSearch;differences=$base.differences;productionContent=[ordered]@{activeDetectionRules=@($detections|Where-Object{$_.enabled-and$_.status-eq'Active'}).Count;sprint32CatalogRules=@($catalog).Count;sprint32Validated=@($catalog|Where-Object validationPassed).Count;activeCorrelationRules=@($correlations|Where-Object{$_.enabled-and$_.status-eq'Active'}).Count};victimQueues=$base.victimQueues;queueTotal=$base.queueTotal;outbox=$base.outbox;nats=$base.nats;passed=$base.passed-and@($catalog).Count-eq30-and@($catalog|Where-Object validationPassed).Count-eq30-and@($correlations|Where-Object{$_.enabled-and$_.status-eq'Active'}).Count-eq18}
$report|ConvertTo-Json -Depth 20|Set-Content artifacts/sprint32-final-reconciliation.json -Encoding utf8;$report|ConvertTo-Json -Depth 20;if(-not$report.passed){throw 'Sprint 32 final reconciliation failed.'}
